This is a Lambda function code that list EC2 instances from multiple regions and write the output to a S3 bucket.
Include name and IP address on the output.
import boto3 import json import os from botocore.exceptions import NoCredentialsError # Set the AWS regions you want to query regions = [&#39;us-east-1&#39;, &#39;us-west-2&#39;, &#39;eu-west-1&#39;] # Set the S3 bucket and object key for storing the output s3_bucket = &#39;your-s3-bucket-name&#39; s3_object_key = &#39;ec2-instances-list.txt&#39; def lambda_handler(event, context): ec2_instances = [] for region in regions: try: # Create an EC2 client for the specified region ec2 = boto3.client(&#39;ec2&#39;, region_name=region) # Describe EC2 instances in the region response = ec2.describe_instances() for reservation in response[&#39;Reservations&#39;]: for instance in reservation[&#39;Instances&#39;]: # Extract instance information instance_name = &#34;N/A&#34; instance_ip = &#34;N/A&#34; for tag in instance.get(&#39;Tags&#39;, []): if tag[&#39;Key&#39;] == &#39;Name&#39;: instance_name = tag[&#39;Value&#39;] if instance.get(&#39;PublicIpAddress&#39;): instance_ip = instance[&#39;PublicIpAddress&#39;] ec2_instances.append(f&#34;Region: {region}, Name: {instance_name}, IP: {instance_ip}&#34;) except NoCredentialsError: return &#34;No AWS credentials found.&#34; # Store the EC2 instance information in an S3 object s3 = boto3.client(&#39;s3&#39;) s3.put_object(Bucket=s3_bucket, Key=s3_object_key, Body=&#39;\n&#39;.join(ec2_instances), ContentType=&#39;text/plain&#39;) return { &#34;statusCode&#34;: 200, &#34;body&#34;: json.dumps(&#34;EC2 instance information has been saved to S3.&#34;) }

