This is a script that fixes /etc/hosts in GCP.
#!/bin/bash # VARIABLES FILE=&#39;/etc/hosts&#39; #BACKUP /etc/hosts before changes cp -ipHR $FILE $FILE_$(date +%Y-%m-%d_%H-%M-%S) # GET IP ADDRESS IP=$(/sbin/ifconfig | grep &#39;inet&#39; | grep -v &#39;inet6&#39; | grep -v &#39;127.0&#39; | cut -d: -f2 | awk &#39;{print $2}&#39; | head -1) # GET HOSTNAME HN=$(/bin/hostname) # GET PROJECT ID echo &#34;169.254.169.254 metadata.google.internal # Added by Google&#34; &gt;&gt; $FILE PR=$(curl -f -s http://metadata.google.internal/computeMetadata/v1/project/project-id -H &#34;Metadata-Flavor: Google&#34;) # ADD HOSTNAME ENTRY TO /etc/hosts STRING=&#34;$IP $HN.mydomain.com&#34; if grep -q &#34;$STRING&#34; &#34;$FILE&#34; then echo &#34;Valid host entry.&#34; else echo &#34;Adding host entry.&#34; echo $STRING $HN &gt;&gt; $FILE fi # DELETE GOOGLE ENTRIES. sed -i &#39;/# Added by Google/d&#39; $FILE # ADD BACK GOOGLE ENTRIES. echo $IP $HN&#34;.c.&#34;$PR&#34;.internal&#34; $HN&#34; # Added by Google&#34; &gt;&gt; $FILE echo &#34;169.254.169.254 metadata.google.internal # Added by Google&#34; &gt;&gt; $FILE # SET PERMISSIONS. chmod 644 $FILE # DISPLAY /etc/hosts cat $FILE Result
127.0.0.1 localhost ::1 localhost ip6-localhost ip6-loopback ff02::1 ip6-allnodes ff02::2 ip6-allrouters 10.128.0.30 test.mydomain.com test 10.128.0.30 test.c.project-id.internal test # Added by Google 169.254.169.254 metadata.google.internal # Added by Google It adds a proper host entry before the Google entries. /etc/hosts has top to bottom precedence.

