Here’s my script to delete AWS LightSail snapshots. It can delete daily or weekly backups and scheduled via crontab. If you want longer or shorter retention, adjust the expired value. It’s in seconds. 604800 is 1 week. 2592000 is 1 month.
#!/bin/bash current=$(date +%s) if [ $# -eq 0 ]; then exit 1 fi if [[ $1 = &#39;daily&#39; ]]; then prefix=&#39;daily&#39; expired=$(($current-604800)) elif [[ $1 = &#39;weekly&#39; ]]; then prefix=&#39;weekly&#39; expired=$(($current-2592000)) else exit 1 fi snaps=&#39;/root/snapshots/snapshots.json&#39; names=&#39;/root/snapshots/names.txt&#39; parse=&#39;/root/snapshots/parse.txt&#39; logfile=&#39;/root/snapshots/snapshots.log&#39; /usr/local/bin/aws lightsail get-instance-snapshots &gt; $snaps cat $snaps | jq -r &#39;.instanceSnapshots[] | .name&#39; &gt; $names cat $names | grep $prefix &gt; $parse while read -r line; do snapshot=$(echo $line | cut -d_ -f3) snapshotname=$line if [ `expr $snapshot + 1 2&gt; /dev/null` ] ; then if [ $snapshot -le $expired ]; then echo &#39;Deleted: &#39;$snapshotname &gt;&gt; $logfile /usr/local/bin/aws lightsail delete-instance-snapshot \ --instance-snapshot-name $snapshotname else echo &#39;Nothing: &#39;$snapshotname &gt;&gt; $logfile fi else echo $snapshot is not numeric &gt; /dev/null fi done &gt; $logfile echo &#39;Expired time: &#39;$expired &gt;&gt; $logfile echo &#39;-----------------------------------&#39; &gt;&gt; $logfile Schedule deletes via crontab.
# run daily at 5am 0 5 * * * /bin/bash /root/snapshots/delete-snapshot.sh daily 2&gt;&amp;1 # run weekly every sunday at 6am 0 6 * * 0 /bin/bash /root/snapshots/delete-snapshot.sh weekly 2&gt;&amp;1

